// Parse and validate input parameters
const input = $input.item.json.body || $input.item.json;

const params = {
  node_name: input.node_name,
  size_gb: parseInt(input.size_gb) || 50,
  storage_class: input.storage_class || 'local-path',
  dry_run: input.dry_run === true || input.dry_run === 'true',
  notify_channel: input.notify_channel || 'cortex-infra',
  request_id: input.request_id || `storage-${Date.now()}`,
  requested_by: input.requested_by || 'cortex-autonomous',
  proxmox_node: input.proxmox_node || 'pve01',
  vm_id: input.vm_id
};

// Validation
const errors = [];
if (!params.node_name) errors.push('node_name is required');
if (params.size_gb < 1 || params.size_gb > 1000) errors.push('size_gb must be between 1 and 1000');
if (!params.vm_id) errors.push('vm_id is required for Proxmox operations');

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      errors: errors,
      params: params
    }
  }];
}

return [{
  json: {
    valid: true,
    params: params,
    timestamp: new Date().toISOString()
  }
}];

// Check current disk usage and determine expansion needs
const params = $input.first().json.params;
const vmStatus = $input.last().json.data;

const currentDiskSize = vmStatus?.maxdisk || 0;
const currentDiskUsed = vmStatus?.disk || 0;
const usagePercent = currentDiskSize > 0 ? (currentDiskUsed / currentDiskSize) * 100 : 0;

return [{
  json: {
    params: params,
    vm_status: {
      name: vmStatus?.name,
      status: vmStatus?.status,
      current_disk_gb: Math.round(currentDiskSize / 1073741824),
      used_disk_gb: Math.round(currentDiskUsed / 1073741824),
      usage_percent: Math.round(usagePercent)
    },
    expansion: {
      new_size_gb: params.size_gb,
      disk_to_expand: 'scsi0',
      needs_expansion: true
    }
  }
}];

// Parse verification output and prepare result
const params = $('Analyze Storage').item.json.params;
const vmStatus = $('Analyze Storage').item.json.vm_status;
const verifyOutput = $input.item.json.stdout || '';

// Parse df output: Filesystem Size Used Avail Use% Mounted
const parts = verifyOutput.trim().split(/\s+/);
const newSize = parts[1] || 'unknown';
const newUsed = parts[2] || 'unknown';
const newAvail = parts[3] || 'unknown';
const newUsePercent = parts[4] || 'unknown';

return [{
  json: {
    success: true,
    action: 'storage_expansion',
    request_id: params.request_id,
    node: params.node_name,
    before: {
      size_gb: vmStatus.current_disk_gb,
      used_gb: vmStatus.used_disk_gb,
      usage_percent: vmStatus.usage_percent
    },
    after: {
      size: newSize,
      used: newUsed,
      available: newAvail,
      usage_percent: newUsePercent
    },
    expansion_gb: params.size_gb,
    timestamp: new Date().toISOString(),
    requested_by: params.requested_by
  }
}];

// Prepare dry-run result without executing
const data = $input.item.json;

return [{
  json: {
    success: true,
    dry_run: true,
    action: 'storage_expansion',
    request_id: data.params.request_id,
    node: data.params.node_name,
    would_execute: [
      `Proxmox: Expand ${data.expansion.disk_to_expand} by ${data.expansion.new_size_gb}GB`,
      `SSH: growpart /dev/sda 3`,
      `SSH: resize2fs /dev/sda3`
    ],
    current_status: data.vm_status,
    timestamp: new Date().toISOString()
  }
}];
